import { useState, useEffect, useCallback } from 'react';
import api from '../../lib/axios';

export const useProduceData = () => {
  const [produce, setProduce] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  // 1. Fetch initial data from the MongoDB database
  const fetchProduce = useCallback(async () => {
    try {
      setIsLoading(true);
      const { data } = await api.get('/produce');
      setProduce(data);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to fetch produce');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchProduce();

    // 2. Establish WebSocket connection for real-time IoT updates
    // Replace HTTP protocol with WS protocol dynamically
    const wsUrl = (process.env.REACT_APP_API_BASE_URL || 'http://localhost:5000')
      .replace('http://', 'ws://')
      .replace('https://', 'wss://')
      .replace('/api', ''); 

    const ws = new WebSocket(wsUrl);

    ws.onopen = () => console.log('Connected to FarmLink Live Sync');

    ws.onmessage = (event) => {
      const message = JSON.parse(event.data);
      
      // When the ESP32 Gateway uploads new data, add it to the top of the UI instantly
      if (message.type === 'NEW_PRODUCE_ADDED') {
        setProduce((prevProduce) => [message.payload, ...prevProduce]);
      }
    };

    ws.onerror = (err) => console.error('WebSocket Error:', err);

    // Cleanup the connection if the user leaves the marketplace page
    return () => {
      if (ws.readyState === 1) ws.close();
    };
  }, [fetchProduce]);

  return { produce, isLoading, error };
};
